        unar = cutlass.Uint32(0)
        bnn = cutlass.Uint32(0)
        nlo = cutlass.Uint32(0)
        uke = cutlass.Uint32(0)
        uk = cutlass.Uint32(0)
        bn = cutlass.Uint32(0)
